#!/usr/bin/env bash
set -Eeuo pipefail
# Self-contained launcher for the audited Phase 208 CI script.
expected=0de0208798ac98bb6b77655e5981f76035666bf4d102473f66189d01ddb9056b
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
base64 --decode > "$tmp.gz" <<'PAYLOAD'

PAYLOAD
gzip -dc "$tmp.gz" > "$tmp"
rm -f "$tmp.gz"
printf '%s  %s\n' "$expected" "$tmp" | sha256sum -c -
exec bash "$tmp" "$@"
